[
  {
    "statement": "Chasing primates with random loud noise shows documented effectiveness for mitigating crop-raiding.",
    "citations": []
  },
  {
    "statement": "Using bright lights to deter primates from crop-raiding has no evidence of effectiveness.",
    "citations": []
  },
  {
    "statement": "In areas where noise deterrents were used along with tree nets, crop raiding by orangutans was reduced.",
    "citations": [
      "1449"
    ]
  },
  {
    "statement": "Chasing gorillas and using random noise resulted in the return of gorillas from plantations to areas close to protected forest.",
    "citations": [
      "1449"
    ]
  },
  {
    "statement": "No evidence was found for the effects of humans chasing primates using bright light to deter crop-raiding.",
    "citations": [
      "1450"
    ]
  },
  {
    "statement": "Loud noise methods have demonstrated positive results in reducing primate crop-raiding behavior.",
    "citations": []
  },
  {
    "statement": "Bright light methods lack any documented evidence of effectiveness for reducing primate crop-raiding.",
    "citations": []
  }
