[
  {
    "statement": "The evidence base for conservation actions designed to mitigate the impacts of commercial logging on primate populations is extremely limited.",
    "citations": []
  },
  {
    "statement": "Out of twelve identified conservation actions, only one action has actual evidence from systematic studies.",
    "citations": []
  },
  {
    "statement": "Three studies provide evidence for the conservation action \"Use selective logging instead of clear-cutting\".",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A site comparison study in Sierra Leone found that primate densities were higher in a forest that had been logged at low intensity than in a forest logged at high intensity.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A before-and-after study in Madagascar found that the number of lemurs increased following selective logging.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A site comparison study in Uganda found that primate densities were similar in a forest that had been logged at low intensity and a forest logged at high intensity.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of using set-asides for primate protection within logging areas.",
    "citations": [
      "1497"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of closing non-essential roads as soon as logging operations are complete.",
    "citations": [
      "1496"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of certifying forest concessions and marketing their products as 'primate friendly'.",
