      "1500"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of reducing the size of forestry teams to include employees only.",
    "citations": [
      "1499"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of implementing road blocks to inspect cars for illegal primate bushmeat.",
    "citations": [
      "1470"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of implementing small and dispersed logging compartments.",
    "citations": [
      "1487"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of thinning trees within forests.",
    "citations": [
      "1491"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of incorporating forested corridors or buffers into logged areas.",
    "citations": [
      "1495"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of providing domestic meat to workers of the logging company to reduce hunting.",
    "citations": [
      "1501"
    ]
  },
  {
    "statement": "There is no evidence from systematic searches for the conservation action of clearing open patches in the forest.",
    "citations": [
      "1490"
    ]
  },
  {
